import{_ as t,o as a,c as r,ai as n}from"./chunks/framework.Ci0kozOl.js";const g=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/architecture/index.md","filePath":"2.0/architecture/index.md","lastUpdated":1786019473000}'),i={name:"2.0/architecture/index.md"};function o(s,e,c,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p><strong>UnoPim</strong> is designed to be an intuitive and easy-to-understand platform. This document provides an overview of the architecture and how UnoPim works.</p><p>UnoPim v2.0.0 is built on top of popular open-source technologies such as <a href="https://php.net" target="_blank" rel="noreferrer">PHP 8.3+</a>, <a href="https://laravel.com" target="_blank" rel="noreferrer">Laravel 12</a>, <a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue.js 3</a>, and <a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS 3</a>, making it a modern, scalable, and flexible PIM solution. The platform also integrates AI capabilities through the <strong>MagicAI</strong> and <strong>AiAgent</strong> packages, enabling intelligent content generation, product enrichment, and conversational PIM management powered by 10+ AI providers.</p><p>As <strong>UnoPim</strong> is tailored for Product Information Management (PIM) needs, it provides both front-end and back-end features that enable businesses to manage product data efficiently while allowing for comprehensive administrative control.</p><p>The architecture is highly modular, with Laravel packages separating each core functionality such as Categories, Products, AI-powered enrichment, and other essential features. This separation of concerns allows for easier customization and extension of the platform. UnoPim v2.0.0 introduces the <strong>AiAgent</strong> package, which provides a conversational AI interface with 32+ PIM-specific tools, and enhances the <strong>MagicAI</strong> package with multi-platform AI provider support and database-backed credential management.</p><p><strong>UnoPim</strong> integrates Vue.js for building dynamic user interfaces, leveraging built-in components to enhance user experience and responsiveness.</p><p>Additionally, <strong>UnoPim</strong> registers various events that can be triggered on most pages, allowing developers to hook into these events and perform custom operations within the application, ensuring flexibility and adaptability in diverse business use cases.</p>',7)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
